const now = new Date();
const greeting = now.getHours() < 12 ? 'Good morning' : now.getHours() < 17 ? 'Good afternoon' : 'Good evening';
const day = now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
const time = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

const systemPrompt = `You are HomeBot, a smart productivity assistant. Generate a daily standup briefing.\n\nCurrent date: ${day}\nCurrent time: ${time}\n\nGenerate a standup report with these sections, using markdown:\n\n1. A greeting with an emoji for the time of day\n2. **Quote of the Day** - one motivational quote relevant to coding/productivity\n3. **Today's Focus Areas** - 3 specific, actionable focus areas for a software developer\n4. **Standup Checklist** - a markdown checklist with common standup items\n5. **Pro Tip** - one practical developer productivity tip\n\nKeep it concise and energetic. Use emojis sparingly.`;

return {
  json: {
    model: 'qwen2.5:7b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `${greeting}! Generate my daily standup briefing.` }
    ],
    stream: false
  }
};

const ollamaRes = $input.item.json;
const content = ollamaRes.message?.content || ollamaRes.response || 'Unable to generate standup report';
return {
  json: {
    output: content,
    data: { assistant: { role: 'assistant', content } }
  }
};
